using System.ComponentModel;
using System.Net;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tool implementations ---
var notebook = new Notebook();
var webSearch = new WebSearcher();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(webSearch.SearchWeb),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// --- Build the chat client with automatic tool invocation ---
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// --- Agent system prompt ---
var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. When given a topic you must:
        1. Search the web 2-3 times with different queries to gather information.
        2. Save each key finding as a note using the note-taking tool.
        3. Retrieve all your notes, then produce a well-structured summary with
           sections, bullet points, and source references.
        Always search before answering. Never fabricate information.
        """),
};

// --- Main loop ---
Console.WriteLine("=== Research Agent ===");
Console.WriteLine("Enter a research topic (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("> ");
    Console.ResetColor();

    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    messages.Add(new(ChatRole.User, input));

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\n[Researching...]\n");
    Console.ResetColor();

    var response = await client.GetResponseAsync(messages, chatOptions);
    messages.AddRange(response.Messages);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine(response.Text);
    Console.ResetColor();
    Console.WriteLine();
}

// ──────────────────────────────────────────────
// Tool: Web Search (uses DuckDuckGo HTML)
// ──────────────────────────────────────────────
sealed class WebSearcher
{
    private readonly HttpClient _http = new();

    [Description("Search the web for a query and return a list of result titles and snippets.")]
    public async Task<string> SearchWeb(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🔍 Searching: \"{query}\"");
        Console.ResetColor();

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var response = await _http.SendAsync(request);
            var html = await response.Content.ReadAsStringAsync();

            var results = ParseResults(html);
            if (results.Count == 0)
                return "No results found.";

            return JsonSerializer.Serialize(results,
                new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseResults(string html)
    {
        var results = new List<SearchResult>();

        // Extract result blocks from DuckDuckGo HTML response
        var titlePattern = new Regex(
            @"<a[^>]+class=""result__a""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);
        var snippetPattern = new Regex(
            @"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>",
            RegexOptions.Singleline);
        var urlPattern = new Regex(
            @"<a[^>]+class=""result__url""[^>]*href=""([^""]*?)""[^>]*>",
            RegexOptions.Singleline);

        var titles = titlePattern.Matches(html);
        var snippets = snippetPattern.Matches(html);
        var urls = urlPattern.Matches(html);

        var count = Math.Min(titles.Count, Math.Min(snippets.Count, 5));
        for (int i = 0; i < count; i++)
        {
            results.Add(new SearchResult
            {
                Title = StripHtml(titles[i].Groups[1].Value),
                Snippet = StripHtml(snippets[i].Groups[1].Value),
                Url = i < urls.Count ? urls[i].Groups[1].Value.Trim() : ""
            });
        }

        return results;
    }

    private static string StripHtml(string html) =>
        WebUtility.HtmlDecode(Regex.Replace(html, "<.*?>", "")).Trim();

    private record SearchResult
    {
        public string Title { get; init; } = "";
        public string Snippet { get; init; } = "";
        public string Url { get; init; } = "";
    }
}

// ──────────────────────────────────────────────
// Tool: Notebook
// ──────────────────────────────────────────────
sealed class Notebook
{
    private readonly List<(string Topic, string Content)> _notes = [];

    [Description("Save a research note. Use this to record key findings.")]
    public string AddNote(
        [Description("Short label for the note")] string topic,
        [Description("The content of the finding")] string content)
    {
        _notes.Add((topic, content));
        Console.ForegroundColor = ConsoleColor.Magenta;
        Console.WriteLine($"  📝 Note saved: \"{topic}\"");
        Console.ResetColor();
        return $"Note #{_notes.Count} saved under \"{topic}\".";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var items = _notes.Select((n, i) =>
            new { Index = i + 1, n.Topic, n.Content });

        return JsonSerializer.Serialize(items,
            new JsonSerializerOptions { WriteIndented = true });
    }
}

